div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Customer</th><th>Car</th><th>Status</th><th>Notes</th></tr></thead><tbody><?php while($r=$refs->fetch_assoc()):?><tr><td><?=e($r['referred_at'])?></td><td><?=e($r['customer_name']?:'—')?></td><td><?=e($r['car_name']?:'—')?></td><td><?=e($r['status'])?></td><td><?=e($r['notes']?:'—')?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
